-- [TSMod] Release join hook (mods/join_release, generated by make_join.py): the 20 recruits join once Anna is in the
-- party (after the Ch.1 battle), at the level the game gives its own late joiners. During the Golden route's squad
-- chapters (Ch.17-20) a recruit without a squad gets its default one (mods/ch17g_plan.md). Silent; never errors out.
local tsmod_join_units = {"UNIT_MASTER_CH_N106", "UNIT_MASTER_CH_N204", "UNIT_MASTER_CH_N005", "UNIT_MASTER_CH_N007", "UNIT_MASTER_CH_N009", "UNIT_MASTER_CH_N104", "UNIT_MASTER_CH_N105", "UNIT_MASTER_CH_N004", "UNIT_MASTER_CH_N006", "UNIT_MASTER_CH_N008", "UNIT_MASTER_CH_N102", "UNIT_MASTER_CH_N203", "UNIT_MASTER_CH_N202", "UNIT_MASTER_CH_N205", "UNIT_MASTER_CH_N207", "UNIT_MASTER_CH_M103", "UNIT_MASTER_CH_N301", "UNIT_MASTER_CH_N101", "UNIT_MASTER_CH_N103", "UNIT_MASTER_CH_N206"}
local tsmod_join_squads = {{"UNIT_MASTER_CH_N101", "B"}, {"UNIT_MASTER_CH_N007", "B"}, {"UNIT_MASTER_CH_N205", "B"}, {"UNIT_MASTER_CH_N004", "B"}, {"UNIT_MASTER_CH_N105", "B"}, {"UNIT_MASTER_CH_M103", "B"}, {"UNIT_MASTER_CH_N301", "B"}, {"UNIT_MASTER_CH_N005", "R"}, {"UNIT_MASTER_CH_N106", "R"}, {"UNIT_MASTER_CH_N204", "R"}, {"UNIT_MASTER_CH_N008", "R"}, {"UNIT_MASTER_CH_N103", "R"}, {"UNIT_MASTER_CH_N206", "R"}, {"UNIT_MASTER_CH_N202", "R"}, {"UNIT_MASTER_CH_N104", "F"}, {"UNIT_MASTER_CH_N006", "F"}, {"UNIT_MASTER_CH_N009", "F"}, {"UNIT_MASTER_CH_N102", "F"}, {"UNIT_MASTER_CH_N207", "F"}, {"UNIT_MASTER_CH_N203", "F"}}
local function tsmod_squad_const(k)
  if k == "B" then return EPartyTeamBenedict elseif k == "R" then return EPartyTeamRoland end
  return EPartyTeamFrederica
end
local function tsmod_squad_key(v)
  if v == nil then return nil end
  if v == EPartyTeamBenedict then return "B" elseif v == EPartyTeamRoland then return "R"
  elseif v == EPartyTeamFrederica then return "F" end
  return nil
end

local function tsmod_golden_squads_active()
  local ok, on = pcall(function()
    local a = GetSysGlobal(SysGlobal.SCENARIO_ANCHOR)
    return a >= EScenarioAnchorSA_MS17S_X38_HD010 and a <= EScenarioAnchorSA_MS20S_X47_HD010
  end)
  return ok and on == true
end
local tsmod_jr_refused_logged = false
local function tsmod_join_release()
  local ok, err = pcall(function()
    if _G ~= nil and rawget(_G, "TSMOD_17G_ACTIVE") then return end     -- the split screen is running
    if IsPartyIn("UNIT_MASTER_CH_P006") ~= true then return end
    local lv = nil
    local refused = {}
    for _, u in ipairs(tsmod_join_units) do
      if IsPartyIn(u) ~= true then
        if JoinParty(u) == true then
          if lv == nil then
            local okl, rec = pcall(GetLastMainBattleRecommendLevel)
            lv = (okl and type(rec) == "number") and rec or 1
            if lv < 1 then lv = 1 elseif lv > 50 then lv = 50 end
          end
          LevelUpToTargetLevel(u, lv)
          if TSLOG ~= nil then pcall(TSLOG, "join", u, "lv", lv) end
        else
          refused[#refused + 1] = u
        end
      end
    end
    if #refused > 0 and not tsmod_jr_refused_logged and TSLOG ~= nil then
      tsmod_jr_refused_logged = true    -- once per level load: a save without the recruits' records refuses every time
      pcall(TSLOG, "join refused (no unit record in this save)", table.concat(refused, " "))
    end
    if tsmod_golden_squads_active() then
      for _, e in ipairs(tsmod_join_squads) do
        if IsPartyIn(e[1]) == true and tsmod_squad_key(GetPartyTeam(e[1])) == nil then
          SetPartyTeam(e[1], tsmod_squad_const(e[2]))
        end
      end
    end
  end)
  if not ok and TSLOG ~= nil then pcall(TSLOG, "join_release: Lua error", err) end
end
local tsmod_jr_orig_sb_thread = CreateScenarioBlockThread
function CreateScenarioBlockThread()
  tsmod_join_release()
  tsmod_jr_orig_sb_thread()
end
